def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.28
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    opp_pressure = 0.0
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0.0)
            prev_bids.append(bid)
            if bid > opp_pressure:
                opp_pressure = bid

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply_tight:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if urgency >= 5:
        target = max(opp_pressure + 2.5, DAILY_SALARY * 0.96)
    elif urgency >= 3:
        target = max(avg_prev + 1.5, DAILY_SALARY * 0.78)
    elif urgency >= 2:
        if supply_loose:
            target = DAILY_SALARY * 0.42
        else:
            target = max(DAILY_SALARY * 0.55, avg_prev * 0.72)
    else:
        if supply_loose:
            target = DAILY_SALARY * 0.26
        else:
            target = DAILY_SALARY * 0.38

    if opp_pressure >= DAILY_SALARY * 1.35 and urgency <= 2:
        target = min(target, DAILY_SALARY * 0.34)

    if rich_count >= 3 and urgency <= 1:
        target = min(target, DAILY_SALARY * 0.3)

    if day >= 8:
        target *= 1.08

    reserve_floor = 0.0
    days_left = 10 - day
    if days_left > 0 and urgency <= 2:
        reserve_floor = min(budget, days_left * DAILY_SALARY * 0.12)

    bid = min(budget - reserve_floor, target)
    if urgency >= 4:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday's trace
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Estimate how many full water units supply can support (for urgency scaling)
    # supply is float; ensure indices only used with int() if needed (none here)
    units_possible = supply / WATER_REQ
    # If supply is tight, bidding more is safer.
    tightness = 0.0
    if units_possible <= 1.0:
        tightness = 1.0
    elif units_possible <= 2.0:
        tightness = 0.6
    else:
        tightness = 0.3

    # Determine target bid relative to yesterday leaders
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        second_prev = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev
    else:
        highest_prev = 0.0
        second_prev = 0.0

    # Base strategy: if someone bid near/above salary threshold, we must match slightly.
    # Cindy averaged ~94 yesterday, so we aim to be competitive around 90-100.
    pressure = 0.0
    if highest_prev >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev >= DAILY_SALARY * 0.7:
        pressure = 0.7
    else:
        pressure = 0.4

    # Urgency from our hp and consecutive no-water days
    urgency = 0.0
    if hp <= 2.0:
        urgency = 1.0
    elif hp <= 4.0:
        urgency = 0.75
    elif hp <= 6.0:
        urgency = 0.5
    else:
        urgency = 0.35

    if no_water_days >= 2:
        urgency = max(urgency, 0.9)
    elif no_water_days == 1:
        urgency = max(urgency, 0.6)

    # Compute bid cap based on budget and need
    # We generally avoid spending too much unless urgency is high.
    budget_fraction = 0.55
    if urgency >= 0.9:
        budget_fraction = 0.95
    elif urgency >= 0.75:
        budget_fraction = 0.8
    elif urgency >= 0.5:
        budget_fraction = 0.65

    # Target bid: try to slightly exceed the previous highest if pressure/tightness/urgency are high
    target = max(DAILY_SALARY * 0.55, highest_prev)

    if pressure >= 0.7 and tightness >= 0.6:
        target = highest_prev + 2.0
    elif pressure >= 0.7:
        target = max(highest_prev, second_prev + 1.5)
    else:
        # If low pressure, bid enough to avoid being undercut by Cindy-like bids
        target = max(target, DAILY_SALARY * 0.7)

    # Add small adjustment if our hp is low
    target += (urgency - 0.5) * 6.0

    # Final bid bounds
    max_affordable = max(0.0, budget * budget_fraction)
    bid = min(max_affordable, target)

    # Ensure non-negative and not absurdly high
    if bid < 0.0:
        bid = 0.0

    return float(bid)

